    tagline: { en: "World-class wines & gourmet getaways", ja: "世界級のワインとグルメな旅", zh: "世界级葡萄酒与美食之旅", ko: "세계적 와인과 미식 여행지" },
    heroImg: "/images/hunter_valley_vineyard.jpg",
